def harmonic(n):
    if n == 1: return 1.0
    return 1.0 / n + harmonic(n - 1)

def bino_coef_recur(n, k):
    if k == 0 or k == n:
        return 1
    return bino_coef_recur(n - 1, k - 1) + bino_coef_recur(n - 1, k)

def reverse(msg):
    if len(msg) <= 1:
        return msg
    return reverse(msg[1:]) + msg[0]  # 또는 msg[-1] + reverse(msg[:-1])

